.dmm-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.dmm-root,.dmm-root *,.dmm-root *::before,.dmm-root *::after{box-sizing:border-box}
.dmm-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.dmm-root img{display:block;border:0;max-width:none}
.dmm-root > [data-node-id]{will-change:transform}
.dmm-root [hidden]{display:none!important}
.dmm-root [data-sh-theme="light"]{display:none!important}
.dmm-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.dmm-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.dmm-root .n2921_763{align-content:stretch;display:flex;gap:15px;align-items:center;position:relative;flex-shrink:0;width:100%;height:41px}
.dmm-root .n2921_764{grid-template-columns:max-content;grid-template-rows:max-content;display:inline-grid;place-items:start;position:relative;flex-shrink:0}
.dmm-root .n2921_765{grid-column:1;grid-template-columns:max-content;grid-template-rows:max-content;display:inline-grid;margin-left:1.78px;margin-top:3.77px;place-items:start;position:relative;grid-row:1}
.dmm-root .n2921_766{grid-column:1;height:25.139px;margin-left:0;margin-top:0;position:relative;grid-row:1;width:23.361px}
.dmm-root .x38{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.dmm-root .n2921_768{grid-column:1;grid-template-columns:max-content;grid-template-rows:max-content;display:inline-grid;margin-left:6.28px;margin-top:1.26px;place-items:start;position:relative;grid-row:1}
.dmm-root .n2921_769{grid-column:1;height:7.783px;margin-left:0;margin-top:0;position:relative;grid-row:1;width:10.055px}
.dmm-root .x39{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
